    bodies:['p = values[:3]\nif any(x < 0 for x in p) or abs(sum(p)-1)>1e-10 or values[6] not in (0,1):\n    raise ValueError("probabilities/capacity")\nif values[6] == 0:\n    return [0,-1,-1]\ni,j = sorted(range(3),key=lambda k:(-p[k],k))[:2]\nreturn [(p[i]*values[3+i]+p[j]*values[3+j])/(p[i]+p[j]),i,j]','const p=values.slice(0,3);\nif(p.some(x=>x<0)||Math.abs(p.reduce((a,b)=>a+b,0)-1)>1e-10||![0,1].includes(values[6]))throw new RangeError("probabilities/capacity");\nif(values[6]===0)return [0,-1,-1];\nconst [i,j]=[0,1,2].sort((a,b)=>p[b]-p[a]||a-b);\nreturn [(p[i]*values[3+i]+p[j]*values[3+j])/(p[i]+p[j]),i,j];','let p=&values[..3];\nif p.iter().any(|x| *x<0.0) || (p.iter().sum::<f64>()-1.0).abs()>1e-10 || (values[6]!=0.0 && values[6]!=1.0) {return Err(InputError);}\nif values[6]==0.0 {return Ok(vec![0.0,-1.0,-1.0]);}\nlet mut ids=[0usize,1,2]; ids.sort_by(|a,b| p[*b].partial_cmp(&p[*a]).unwrap().then(a.cmp(b))); let (i,j)=(ids[0],ids[1]);\nOk(vec![(p[i]*values[3+i]+p[j]*values[3+j])/(p[i]+p[j]),i as f64,j as f64])'],cases:[[[.5,.3,.2,2,4,100,1],[2.75,0,1]],[[.25,.25,.5,2,4,8,1],[6,2,0]],[[.5,.3,.2,2,4,100,0],[0,-1,-1]]],
