    bodies:['h0,h1,w0,w1,index,replacement = values\nif index not in (0,1):\n    raise ValueError("index")\nh,w = [h0,h1],[w0,w1]\nbase = w0*h0+w1*h1\ne = w[int(index)]*(replacement-h[int(index)])\nreturn [base,base+e,e]','const [h0,h1,w0,w1,index,replacement]=values;\nif(![0,1].includes(index))throw new RangeError("index");\nconst base=w0*h0+w1*h1,e=[w0,w1][index]*(replacement-[h0,h1][index]);\nreturn [base,base+e,e];','let k=values[4];if k!=0.0 && k!=1.0 {return Err(InputError);}\nlet i=k as usize;let base=values[2]*values[0]+values[3]*values[1];let e=values[2+i]*(values[5]-values[i]);\nOk(vec![base,base+e,e])'],cases:[[[2,3,1,-2,1,0],[-4,2,6]],[[2,3,1,-2,1,3],[-4,-4,0]],[[2,3,0,-2,0,100],[-6,-6,0]]],
