function code(fragment: Fragment): Pick<PracticeExercise,'starter'|'solution'> {
  const shape = fragment.size ? `len(values) != ${fragment.size}` : 'not 4 <= len(values) <= 35';
  const jsShape = fragment.size ? `values.length!==${fragment.size}` : '(values.length<4||values.length>35)';
  const rsShape = fragment.size ? `values.len()!=${fragment.size}` : '(values.len()<4 || values.len()>35)';
  const py = (body:string) => 'import math\n\ndef solve(values: list[float]) -> list[float]:\n'+body.split('\n').map(line=>'    '+line).join('\n')+'\n';
  const js = (body:string) => 'function solve(values) {\n'+body.split('\n').map(line=>'  '+line).join('\n')+'\n}\n';
  const rs = (body:string) => '#[derive(Debug, PartialEq)]\npub struct InputError;\npub fn solve(values: &[f64]) -> Result<Vec<f64>,InputError> {\n'+body.split('\n').map(line=>'    '+line).join('\n')+'\n}\n';
  return {
    starter:{python:py('raise NotImplementedError("Реализуйте формулу и контракт")'),javascript:js('throw new Error("Реализуйте формулу и контракт");'),rust:rs('todo!("Реализуйте формулу и контракт")')},
    solution:{
      python:py(`if not isinstance(values,list) or ${shape} or any(isinstance(x,bool) or not isinstance(x,(int,float)) or not math.isfinite(x) or abs(x)>1000 for x in values):\n    raise ValueError("Форма, конечные числа, предел ±1000")\n`+fragment.bodies[0]),
      javascript:js(`if(!Array.isArray(values)||${jsShape}||values.some(x=>typeof x!=="number"||!Number.isFinite(x)||Math.abs(x)>1000))throw new RangeError("Форма, конечные числа, предел ±1000");\n`+fragment.bodies[1]),
      rust:rs(`if ${rsShape} || values.iter().any(|x| !x.is_finite() || x.abs()>1000.0) {return Err(InputError);}\n`+fragment.bodies[2]),
    },
  };
}

function understandingQuiz(fragment:Fragment,index:number):PracticeExercise['quiz'] {
  const options=[misconception[fragment.id],'Один верный fixture доказывает полное освоение родительской модели.'];
  options.splice(index,0,fragment.checks[index]);
  return {
    question:`${index===0?'Проверьте формулу':index===1?'Перенос A':'Перенос B'}: какое утверждение верно для «${fragment.title}»?`,
    options,correctIndex:index,explanation:`${fragment.checks[index]} ${fragment.hint}`,
  };
}

